declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');$base=__DIR__.'/data';if(!is_dir($base))@mkdir($base,0775,true);$rf=$base.'/community-recipes.json';$vf=$base.'/recipe-reviews.json';function rj($f){if(!file_exists($f))return[];$d=json_decode(file_get_contents($f),true);return is_array($d)?$d:[];}function wj($f,$d){$h=fopen($f,'c+');if(!$h)return false;flock($h,LOCK_EX);ftruncate($h,0);rewind($h);fwrite($h,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));fflush($h);flock($h,LOCK_UN);fclose($h);return true;}$a=$_GET['action']??'';$m=$_SERVER['REQUEST_METHOD'];if($m==='GET'&&$a==='recipes'){echo json_encode(rj($rf),JSON_UNESCAPED_UNICODE);exit;}if($m==='GET'&&$a==='reviews'){echo json_encode(rj($vf),JSON_UNESCAPED_UNICODE);exit;}$b=json_decode(file_get_contents('php://input')?:'{}',true);if($m==='POST'&&$a==='recipe'){$b['id']='srv_'.bin2hex(random_bytes(6));$b['status']='pending';$d=rj($rf);$d[]=$b;wj($rf,$d);echo json_encode(['ok'=>true,'id'=>$b['id']]);exit;}if($m==='POST'&&$a==='review'){$b['id']='rev_'.bin2hex(random_bytes(6));$b['status']='pending';$d=rj($vf);$d[]=$b;wj($vf,$d);echo json_encode(['ok'=>true]);exit;}http_response_code(404);echo json_encode(['error'=>'Unbekannte Aktion']);